entry.summary:
ok-idiom

使用 value, ok := map[key] 的语法保证百分之百安全

//通过ok-idiom来判断key value是否存在，并获取map
if value, ok := map1[1]; ok {
    fmt.Println(&quot;map key存在,其值为:&quot;, value)
}


示例

